const settleHumanNeededByComment = `-- name: SettleHumanNeededByComment :many
UPDATE human_needed_event
SET status = 'answered', answered_at = now(), answer_comment_id = $3,
    woken_at = COALESCE(woken_at, now()), relayed_at = COALESCE(relayed_at, now())
WHERE issue_id = $1 AND target_user_id = $2 AND summon_id IS NULL
  AND event_type = 'human_needed'
  AND status IN ('sent', 'woken', 'relayed')
RETURNING sequence, event_id, workspace_id, bot_id, binding_id, target_user_id, event_type, parent_event_id, kind, dedupe_key, issue_id, chat_session_id, summon_id, inbox_item_id, source_comment_id, ask_id, caller_type, caller_id, question, options, urgency, deadline, status, reason, attempts, next_attempt_at, created_at, sent_at, woken_at, relayed_at, relay_channel, relay_ref, answered_at, answer, answer_comment_id, escalated_at, last_nudge_at, expires_at, activity
`

type SettleHumanNeededByCommentParams struct {
	IssueID         pgtype.UUID `json:"issue_id"`
	TargetUserID    pgtype.UUID `json:"target_user_id"`
	AnswerCommentID pgtype.UUID `json:"answer_comment_id"`
}

// A person's reply under a mention-sourced event (no summon behind it) is the
// answer.
func (q *Queries) SettleHumanNeededByComment(ctx context.Context, arg SettleHumanNeededByCommentParams) ([]HumanNeededEvent, error) {
	rows, err := q.db.Query(ctx, settleHumanNeededByComment, arg.IssueID, arg.TargetUserID, arg.AnswerCommentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []HumanNeededEvent{}
	for rows.Next() {
		var i HumanNeededEvent
		if err := rows.Scan(
			&i.Sequence,
			&i.EventID,
			&i.WorkspaceID,
			&i.BotID,
			&i.BindingID,
			&i.TargetUserID,
			&i.EventType,
			&i.ParentEventID,
			&i.Kind,
			&i.DedupeKey,
			&i.IssueID,
			&i.ChatSessionID,
			&i.SummonID,
			&i.InboxItemID,
			&i.SourceCommentID,
			&i.AskID,
			&i.CallerType,
			&i.CallerID,
			&i.Question,
			&i.Options,
			&i.Urgency,
			&i.Deadline,
			&i.Status,
			&i.Reason,
			&i.Attempts,
			&i.NextAttemptAt,
			&i.CreatedAt,
			&i.SentAt,
			&i.WokenAt,
			&i.RelayedAt,
			&i.RelayChannel,
			&i.RelayRef,
			&i.AnsweredAt,
			&i.Answer,
			&i.AnswerCommentID,
			&i.EscalatedAt,
			&i.LastNudgeAt,
			&i.ExpiresAt,
			&i.Activity,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const settleHumanNeededBySummons = `-- name: SettleHumanNeededBySummons :exec
UPDATE human_needed_event e
SET status = CASE WHEN s.answer_comment_id IS NOT NULL THEN 'answered' ELSE 'cancelled' END,
    answered_at = CASE WHEN s.answer_comment_id IS NOT NULL THEN now() ELSE e.answered_at END,
    answer_comment_id = COALESCE(e.answer_comment_id, s.answer_comment_id),
    reason = CASE WHEN s.answer_comment_id IS NOT NULL THEN e.reason ELSE 'source closed' END
FROM issue_summon s
WHERE e.summon_id = s.id AND s.id = ANY($1::uuid[])
  AND e.status IN ('queued', 'sending', 'sent', 'woken', 'relayed')
`

// The source call ended (the person answered in the app, or the ticket moved
// on): the Bot no longer needs to chase it.
func (q *Queries) SettleHumanNeededBySummons(ctx context.Context, dollar_1 []pgtype.UUID) error {
	_, err := q.db.Exec(ctx, settleHumanNeededBySummons, dollar_1)
	return err
}

const touchHumanNeededNudge = `-- name: TouchHumanNeededNudge :exec
UPDATE human_needed_event SET last_nudge_at = now() WHERE event_id = $1
`

func (q *Queries) TouchHumanNeededNudge(ctx context.Context, eventID pgtype.UUID) error {
	_, err := q.db.Exec(ctx, touchHumanNeededNudge, eventID)
	return err
}

const updateMemberBotBindingSettings = `-- name: UpdateMemberBotBindingSettings :one
UPDATE member_bot_binding
SET mode = $2, resend_after_seconds = $3, escalate_after_seconds = $4, updated_at = now()
WHERE id = $1 AND revoked_at IS NULL
RETURNING id, workspace_id, user_id, bot_id, mode, resend_after_seconds, escalate_after_seconds, created_at, updated_at, verified_at, revoked_at, broken_notified_at, activity_scope
`

type UpdateMemberBotBindingSettingsParams struct {
	ID                   pgtype.UUID `json:"id"`
	Mode                 string      `json:"mode"`
	ResendAfterSeconds   int32       `json:"resend_after_seconds"`
	EscalateAfterSeconds int32       `json:"escalate_after_seconds"`
}

func (q *Queries) UpdateMemberBotBindingSettings(ctx context.Context, arg UpdateMemberBotBindingSettingsParams) (MemberBotBinding, error) {
	row := q.db.QueryRow(ctx, updateMemberBotBindingSettings,
		arg.ID,
		arg.Mode,
		arg.ResendAfterSeconds,
		arg.EscalateAfterSeconds,
	)
	var i MemberBotBinding
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.UserID,
		&i.BotID,
		&i.Mode,
		&i.ResendAfterSeconds,
		&i.EscalateAfterSeconds,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.VerifiedAt,
		&i.RevokedAt,
		&i.BrokenNotifiedAt,
		&i.ActivityScope,
	)
	return i, err
}

const verifyMemberBotBinding = `-- name: VerifyMemberBotBinding :exec
UPDATE member_bot_binding
SET verified_at = COALESCE(verified_at, now()), broken_notified_at = NULL, updated_at = now()
WHERE id = $1 AND revoked_at IS NULL
`

func (q *Queries) VerifyMemberBotBinding(ctx context.Context, id pgtype.UUID) error {
	_, err := q.db.Exec(ctx, verifyMemberBotBinding, id)
	return err
}
